import type { PerformanceAndBreakdownWaterfallData } from '../../types';
import { PERFORMANCE_AND_BREAKDOWN_BRANDS } from '../assets/brandImageUrls';
import { PERFORMANCE_AND_BREAKDOWN_FLAGS } from '../assets/flags';
import { buildPerformanceAndBreakdownDeepDiveDrillComparisonLines } from './deepDiveLayerComparisonLines';
import {
  PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_LE_VALUE,
  PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX,
} from './deepDiveWaterfallPrefix';

type CountryFlagKey = keyof typeof PERFORMANCE_AND_BREAKDOWN_FLAGS.countries;

const BRA_FIGMA_BRANDS: Array<{
  name: string;
  imageKey: keyof typeof PERFORMANCE_AND_BREAKDOWN_BRANDS;
}> = [
  { name: 'Corona', imageKey: 'corona' },
  { name: 'Budweiser', imageKey: 'budweiser' },
  { name: 'Michelob', imageKey: 'michelob' },
  { name: 'Stella Artois', imageKey: 'stella_artois' },
  { name: 'Spaten', imageKey: 'others' },
  { name: 'Castle', imageKey: 'others' },
  { name: 'Quilmes', imageKey: 'pilsen' },
  { name: 'Original', imageKey: 'others' },
  { name: 'Brahma', imageKey: 'brahma' },
  { name: 'Goose Island', imageKey: 'others' },
  { name: "Beck's", imageKey: 'others' },
  { name: 'Patagonia', imageKey: 'others' },
  { name: 'Skol', imageKey: 'skol' },
];

function buildBrandByCountryMock(
  countryCode: CountryFlagKey,
  brands: Array<{
    name: string;
    imageKey: keyof typeof PERFORMANCE_AND_BREAKDOWN_BRANDS;
  }>,
  comparisonLines = buildPerformanceAndBreakdownDeepDiveDrillComparisonLines(
    PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.labels.length +
      brands.length +
      2,
  ),
): PerformanceAndBreakdownWaterfallData {
  const brandValues = [
    12.4, 9.6, 7.8, 5.2, 4.1, 3.8, 3.2, 2.8, 2.1, 1.8, 1.5, 1.2, 0.9,
  ].slice(0, brands.length);
  const formattedBrandValues = brandValues.map((value) => `+${value}`);
  const othersValue = -1.4;
  const leValue = PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_LE_VALUE;
  const lastIndex =
    PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.labels.length +
    brands.length +
    1;
  const othersIndex = lastIndex - 1;
  const countryFlag = {
    src: PERFORMANCE_AND_BREAKDOWN_FLAGS.countries[countryCode],
    alt: countryCode,
  };

  const prefixImages =
    PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.images.map(
      (item, index) =>
        index === 2 ? { ...item, badgeFlag: countryFlag } : { ...item },
    );

  return {
    values: [
      ...PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.values,
      ...brandValues,
      othersValue,
      leValue,
    ],
    labels: [
      ...PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.labels,
      ...brands.map((item) => item.name),
      'Others',
      "'26 LE",
    ],
    formattedData: [
      [
        ...PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.formatted,
        ...formattedBrandValues,
        String(othersValue),
        String(leValue),
      ],
    ],
    specialIndexes: { first: 0, last: lastIndex },
    disabledIndexes: [
      ...PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.disabledIndexes,
      othersIndex,
      lastIndex,
    ],
    clickableIndexes: brands.map(
      (_, index) =>
        PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.labels.length +
        index,
    ),
    filterValues: [
      ...PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.filterValues,
      ...brands.map((item) => item.name),
      null,
      null,
    ],
    images: {
      data: [
        ...prefixImages,
        ...brands.map((item) => ({
          title: item.name,
          mainBrand: {
            src: PERFORMANCE_AND_BREAKDOWN_BRANDS[item.imageKey],
            alt: item.name,
          },
        })),
        {
          title: 'Others',
          mainBrand: {
            src: PERFORMANCE_AND_BREAKDOWN_BRANDS.others,
            alt: 'Others',
          },
        },
        {
          title: "'26 LE",
          badgeFlag: countryFlag,
        },
      ],
    },
    comparisonLine: { data: comparisonLines },
  };
}

export const PerformanceAndBreakdownDeepDiveBrandByCountryMap: Record<
  string,
  PerformanceAndBreakdownWaterfallData
> = {
  BRA: buildBrandByCountryMock(
    'BRA',
    BRA_FIGMA_BRANDS,
    buildPerformanceAndBreakdownDeepDiveDrillComparisonLines(18),
  ),
  COL: buildBrandByCountryMock('COL', [
    { name: 'Aguila', imageKey: 'aguila' },
    { name: 'Pilsen', imageKey: 'pilsen' },
    { name: 'Budweiser', imageKey: 'budweiser' },
    { name: 'Corona', imageKey: 'corona' },
  ]),
  ARG: buildBrandByCountryMock('ARG', [
    { name: 'Brahma', imageKey: 'brahma' },
    { name: 'Stella Artois', imageKey: 'stella_artois' },
    { name: 'Corona', imageKey: 'corona' },
    { name: 'Budweiser', imageKey: 'budweiser' },
  ]),
  BEL: buildBrandByCountryMock('BEL', [
    { name: 'Stella Artois', imageKey: 'stella_artois' },
    { name: 'Budweiser', imageKey: 'budweiser' },
    { name: 'Corona', imageKey: 'corona' },
  ]),
  USA: buildBrandByCountryMock('USA', [
    { name: 'Budweiser', imageKey: 'budweiser' },
    { name: 'Bud Light', imageKey: 'bud_light' },
    { name: 'Busch', imageKey: 'busch' },
    { name: 'Michelob', imageKey: 'michelob' },
  ]),
  MEX: buildBrandByCountryMock('MEX', [
    { name: 'Corona', imageKey: 'corona' },
    { name: 'Modelo', imageKey: 'modelo' },
    { name: 'Victoria', imageKey: 'victoria' },
  ]),
  CHN: buildBrandByCountryMock('CHN', [
    { name: 'Budweiser', imageKey: 'budweiser' },
    { name: 'Corona', imageKey: 'corona' },
    { name: 'Stella Artois', imageKey: 'stella_artois' },
  ]),
  ZAF: buildBrandByCountryMock('ZAF', [
    { name: 'Carling', imageKey: 'carling' },
    { name: 'Stella Artois', imageKey: 'stella_artois' },
    { name: 'Corona', imageKey: 'corona' },
  ]),
  BOL: buildBrandByCountryMock('BOL', [
    { name: 'Corona', imageKey: 'corona' },
    { name: 'Budweiser', imageKey: 'budweiser' },
    { name: 'Skol', imageKey: 'skol' },
  ]),
  KOR: buildBrandByCountryMock('KOR', [
    { name: 'Budweiser', imageKey: 'budweiser' },
    { name: 'Corona', imageKey: 'corona' },
    { name: 'Stella Artois', imageKey: 'stella_artois' },
  ]),
  PER: buildBrandByCountryMock('PER', [
    { name: 'Pilsen', imageKey: 'pilsen' },
    { name: 'Corona', imageKey: 'corona' },
    { name: 'Budweiser', imageKey: 'budweiser' },
  ]),
  FRA: buildBrandByCountryMock('FRA', [
    { name: 'Stella Artois', imageKey: 'stella_artois' },
    { name: 'Corona', imageKey: 'corona' },
    { name: 'Budweiser', imageKey: 'budweiser' },
  ]),
};

export const PerformanceAndBreakdownDeepDiveBrandByCountryWaterfallMock =
  PerformanceAndBreakdownDeepDiveBrandByCountryMap.BRA;
